    int64_t inner_idx = idx % inner;

    float sum = 0.0f;
    int64_t base = outer_idx * reduce_size * inner + inner_idx;
    for (int64_t r = 0; r < reduce_size; r++) {
        sum += input[base + r * inner];
    }
    output[outer_idx * inner + inner_idx] = sum;
